 25	    static List<Integer> topologicalSort(List<? extends List<Integer>> adjacencyList) {
 26	        int vertexCount = adjacencyList.size();
 27	        int[] indegree = calculateIndegrees(adjacencyList, vertexCount);
 28	        Deque<Integer> readyVertices = collectZeroIndegreeVertices(indegree);
 29	        List<Integer> sortedVertices = new ArrayList<>(vertexCount);
 30	
 31	        while (!readyVertices.isEmpty()) {
 32	            int vertex = readyVertices.removeFirst();
 33	            sortedVertices.add(vertex);
 34	            enqueueReadyNeighbors(adjacencyList.get(vertex), indegree, readyVertices);
 35	        }
 36	
 37	        return sortedVertices;
 38	    }
