 52	    private static int[] calculateIndegrees(List<? extends List<Integer>> adjacencyList, int vertexCount) {
 53	        int[] indegree = new int[vertexCount];
 54	        for (List<Integer> neighbors : adjacencyList) {
 55	            for (int next : neighbors) {
 56	                indegree[next]++;
 57	            }
 58	        }
 59	        return indegree;
 60	    }
 61	
 62	    private static Deque<Integer> collectZeroIndegreeVertices(int[] indegree) {
 63	        Deque<Integer> readyVertices = new ArrayDeque<>();
 64	        for (int vertex = 0; vertex < indegree.length; vertex++) {
 65	            if (indegree[vertex] == 0) {
 66	                readyVertices.addLast(vertex);
 67	            }
 68	        }
 69	        return readyVertices;
 70	    }
 71	
 72	    private static void enqueueReadyNeighbors(
 73	            List<Integer> neighbors,
 74	            int[] indegree,
 75	            Deque<Integer> readyVertices
 76	    ) {
 77	        for (int next : neighbors) {
 78	            indegree[next]--;
 79	            if (indegree[next] == 0) {
 80	                readyVertices.addLast(next);
 81	            }
 82	        }
 83	    }
