 85	    private static List<List<Integer>> createGraph(int vertexCount) {
 86	        List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
 87	        for (int i = 0; i < vertexCount; i++) {
 88	            adjacencyList.add(new ArrayList<>());
 89	        }
 90	        return adjacencyList;
 91	    }
